            ds.recordHistory = []; ds.hoursHistory = []; ds.cumHistory = [];
            for (i = 0; i < per.length; i++) {
                ds.profitHistory[i] = Math.round(per[i].profit);
                ds.hourlyHistory[i] = Math.round(per[i].hourly * 100) / 100;
                ds.customersHistory[i] = per[i].kept;
                ds.repHistory[i] = Math.round(per[i].rep);
                ds.recordHistory[i] = Math.round(per[i].rec);
                ds.hoursHistory[i] = Math.round(per[i].hours * 10) / 10;
                ds.cumHistory[i] = Math.round(per[i].cum);
            }
            ds.roundScores[period - 1] = rs.score;
            ds.scoreHistory[period - 1] = rs.score;
            ds.hardFail = rs.m.hard;
            var q = period - 1;
            ds.last = { roundScore: rs.score, profit: ds.profitHistory[q], hourly: ds.hourlyHistory[q], customers: ds.customersHistory[q],
                        rep: ds.repHistory[q], record: ds.recordHistory[q], hours: ds.hoursHistory[q], cum: ds.cumHistory[q],
                        tax: Math.round(per[q].se), hard: rs.m.hard };
            var score = this._composite(state);
            ds.performance = { overallScore: score };
            out.overallScore = score;
            out.score = score;
            out.roundScore = rs.score;
            out.profit = ds.last.profit;
            out.hourly = ds.last.hourly;
            out.customers = ds.last.customers;
            out.rep = ds.last.rep;
            out.record = ds.last.record;
            out.hours = ds.last.hours;
            out.cum = ds.last.cum;
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextPeriod = period + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextPeriod); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, period, g) {
            if (this.ROUND_OF[g] <= period) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _summer(dec, k) {
            var c = this.C;
            var per = [];
            var acc = c.START_ACC;
            var repPrev = c.REP0;
            var qPrev = 75.0;
            var wait = 0.0;
            var cum = 0.0;
            var i, p;
            for (p = 1; p <= 4; p++) {
                var a = {};
                for (i = 0; i < this.KEYS.length; i++) { a[this.KEYS[i]] = this._active(dec, p, this.KEYS[i]); }
                var pr = this.PRICE[a.price1];
                var price = pr[0], conv = pr[1], pchurn = pr[2], pRep = pr[3];
                var ge = this.GEAR[a.gear1];
                var tmin = ge[0], qual = ge[1], perCost = ge[3], visitCost = ge[4], brkCost = ge[5], brkLost = ge[6];
                var mk = this.MKT[a.mkt2];
                var mLeads = mk[0], mRef = mk[1], travel = mk[2], mCost = mk[3], mRep = mk[4], mRec = mk[5];
                var bk = this.BOOK[a.book2];
                var unc = bk[0], bRec = bk[1], bAdmin = bk[2], bRep = bk[3];
                var cp = this.CAP[a.cap3];
                var cRep = cp[0], cCapm = cp[1], cTrm = cp[2], cDem = cp[3], cUp = cp[4], cShare = cp[5];
                var ad = (p >= 3) ? this.ADD[a.add3] : this.ADD.none;
                var adRev = ad[0], adHrs = ad[1], adCost = ad[2], adRep = ad[3], adRec = ad[4], adLoss = ad[5];
                var hard = 0;
                for (i = 0; i < this.HARD.length; i++) {
                    if (a[this.HARD[i][0]] === this.HARD[i][1] && p >= this.ROUND_OF[this.HARD[i][0]]) { hard += 1; }
                }
                var hoursWk = c.HOURS[p - 1];
                var fRep = 0.0, fRec = 0.0, fKeep = 1.0, fOne = 0.0, fOver = 0;
                if (p === 4) {
                    var fa = this.FALL[a.fall4];
                    hoursWk = fa[0]; fRep = fa[1]; fRec = fa[2]; fKeep = fa[3]; fOne = fa[4]; fOver = fa[5];
                }
                travel *= cTrm;
                var leads = ((p === 1) ? this.P1_LEADS : mLeads) + mRef * acc * (repPrev / 70.0);
                if (p >= 2) { leads += 0.5 * wait; }
                if (p === 3) { leads += c.HOA_LEADS; }
                var repF = this._clamp(repPrev / 70.0, 0.6, 1.2);
                var nw = leads * conv * repF;
                var churn = this._clamp((c.CHURN_Q - qPrev) / c.CHURN_DIV, c.CHURN_MIN, c.CHURN_MAX) + pchurn;
                var demand = this._jsround((acc * (1.0 - churn) + nw) * cDem);
                var capOne = Math.floor(hoursWk * 60.0 / (tmin + travel));
                var capacity = Math.floor(capOne * cCapm);
                var handled = (p >= 3) ? a.cap3 : this.REF.cap3;
                if (p === 4 && fOver) { handled = 'yesall'; }
                var served;
                if (p === 4 && fKeep === 0.0) {
                    served = 0;
                } else if (handled === 'yesall') {
                    served = demand;
                } else {
                    served = Math.min(demand, capacity);
                }
                wait = (handled === 'waitlist') ? Math.max(0.0, demand - served) : 0.0;
                var handoff = (p === 4 && a.fall4 === 'weekend') ? Math.max(0, demand - served) : 0;
                var iCash = 0.0, iRep = 0.0, iLost = 0, iRec = 0.0;
                if (p === 4) {
                    var ic = this.INC[a.inc4];
                    iCash = ic[0]; iRep = ic[1]; iLost = ic[2]; iRec = ic[3];
                    if (served > 0) {
                        served = served - Math.min(iLost, served);
                    }
                }
                var visits = served * c.WEEKS;
                var ownAcc = (cShare > 0) ? Math.min(served, capOne) : served;
                var partAcc = served - ownAcc;
                var needWk = ownAcc * (tmin + travel) / 60.0;
                var overload = 0.0;
                if (handled === 'yesall' && served > 0) {
                    overload = this._clamp(needWk / hoursWk - 1.0, 0.0, c.OVER_MAX);
                }
                var missed = c.OVER_MISS * overload;
                if (p === 2) { missed += brkLost; }
                var qualP = qual - c.OVER_Q * overload - ((partAcc > 0) ? 5.0 : 0.0) * (partAcc / Math.max(served, 1));
                var pv = (price === null) ? (this.HOURLY_RATE * (tmin + 0.0) / 60.0) : price;
                var pvEff = pv + ((p >= 3) ? cUp : 0.0);
                var gross = visits * pvEff * (1.0 - missed);
                var partCut = (partAcc * c.WEEKS * pvEff * (1.0 - missed)) * cShare;
                var addRev = (a.add3 !== 'pressure') ? adRev * served : adRev;
                if (p < 3) { addRev = 0.0; }
                var addHours = (a.add3 !== 'pressure') ? adHrs * served : this.PRESSURE_HOURS;
                if (p < 3) { addHours = 0.0; }
                var closed = (p === 4 && fKeep === 0.0);
                if (closed) {
                    addRev = 0.0;
                    addHours = 0.0;
                }
                var revenue = gross + addRev;
                var uncollected = revenue * unc;
                var supplies = visits * (1.0 - missed) * (c.SUPPLIES + c.TRAVEL_COST * travel + visitCost);
                var equip = perCost + ((p === 2) ? brkCost : 0.0);
                var mcost = (p === 1 || closed) ? 0.0 : mCost;
                var acost = (p >= 3 && !closed) ? adCost : 0.0;
                var loss = (p === 4 && a.add3 === 'weedfeed') ? adLoss : 0.0;
                var feeDisp = (p >= 3 && a.cap3 === 'partner' && a.book2 === 'pocket') ? 150.0 : 0.0;
                var finder = this.FINDER * handoff;
                var costs = supplies + equip + mcost + acost + loss + partCut + iCash + feeDisp;
                var profit = revenue - uncollected - costs + fOne + finder;
                var hours = ownAcc * c.WEEKS * (1.0 - missed) * (tmin + travel) / 60.0 + (closed ? 0.0 : bAdmin * c.WEEKS) + addHours;
                var hourly = (hours > 0) ? profit / hours : 0.0;
                var rep = (c.REP0 + (qualP - 75.0) / 2.0 + pRep + ((p >= 2) ? mRep : 0.0)
                    + ((p >= 2) ? bRep : 0.0) + ((p >= 3) ? (cRep + adRep) : 0.0)
                    - c.OVER_REP * overload + ((p === 4) ? (fRep + iRep) : 0.0));
                if (p === 2 && brkLost) { rep -= 4.0; }
                rep = this._clamp(rep, 0.0, 100.0);
                var kept = served;
                if (p === 4) {
                    kept = this._jsround(served * this._clamp((rep - c.R_LO) / (c.R_HI - c.R_LO), 0.0, 1.0));
                }
                var rec = this._clamp(((p === 1) ? this.BOOK.notebook[1] : bRec) + ((p >= 2) ? mRec : 0.0)
                    + ((p >= 3) ? adRec : 0.0) + ((p === 4) ? (fRec + iRec) : 0.0)
                    - ((p >= 3 && a.cap3 === 'partner' && a.book2 === 'pocket') ? 10.0 : 0.0), 0.0, 100.0);
                cum += profit;
                var se = (c.SE_BASE * cum >= c.SE_MIN) ? c.SE_RATE * c.SE_BASE * cum : 0.0;
                per.push({ p: p, served: served, kept: kept, profit: profit, hours: hours, hourly: hourly, rep: rep, rec: rec,
                           cum: cum, se: se, hard: hard, a: a });
                acc = served;
                repPrev = rep;
                qPrev = qualP;
                if (p >= k) { break; }
            }
            var last = per[per.length - 1];
            return { per: per, p: last.p, served: last.served, kept: last.kept, profit: last.profit, hours: last.hours, hourly: last.hourly,
                     rep: last.rep, rec: last.rec, cum: last.cum, se: last.se, hard: last.hard, a: last.a };
        }

        _components(r) {
            var c = this.C;
            var pc = this._clamp((r.profit - c.P_LO) / (c.P_HI[r.p - 1] - c.P_LO), 0, 1);
            var hc = this._clamp((r.hourly - c.H_LO) / (c.H_HI - c.H_LO), 0, 1);
            var ac = this._clamp((r.kept - c.A_LO) / (c.A_HI[r.p - 1] - c.A_LO), 0, 1);
            var rc = this._clamp((r.rep - c.R_LO) / (c.R_HI - c.R_LO), 0, 1);
            var kc = this._clamp((r.rec - c.K_LO) / (c.K_HI - c.K_LO), 0, 1);
            return [pc, hc, ac, rc, kc];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._summer(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_P, c.W_H, c.W_A, c.W_R, c.W_K];
            var tw = 0, num = 0, i;
            for (i = 0; i < 5; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.PERIOD_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var v = window.vcI18n;
            if (v && v._lang) { return v._lang; }
            var html = (typeof document !== 'undefined' && document.documentElement) ? document.documentElement.lang : '';
            return html ? String(html).slice(0, 2) : 'en';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = ',' + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + '.' + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _fmtUsd(n) {
            var v = Math.round(Math.abs(n));
            return (n < 0 && v > 0 ? '-$' : '$') + this._fmtInt(v);
        }

        _fmtUsd2(n) {
            if (n === null || n === undefined) { return '-'; }
            var v = Math.round(Math.abs(n) * 100);
            var whole = Math.floor(v / 100);
            var cents = v - whole * 100;
            return (n < 0 && v > 0 ? '-$' : '$') + this._fmtInt(whole) + '.' + (cents < 10 ? '0' : '') + String(cents);
        }

        _sum(arr) {
            var s = 0, i;
            for (i = 0; i < arr.length; i++) { s += arr[i]; }
            return s;
        }

        _syncControlsFromDecisions(state, forcePeriod) {
            var period = forcePeriod || (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcePeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcePeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var pH = ds.profitHistory || [];
            var hH = ds.hourlyHistory || [];
            var cH = ds.customersHistory || [];
            var rH = ds.repHistory || [];
            var kH = ds.recordHistory || [];
            var oH = ds.hoursHistory || [];
            var uH = ds.cumHistory || [];
            var n = pH.length;
            var last = ds.last || {};
            this._set('profitDisplay', n ? (this._fmtUsd(pH[n - 1]) + ' · ' + this._t('txt_total') + ' ' + this._fmtUsd(uH[n - 1])) : '-');
            this._set('hourlyDisplay', n ? this._fmtUsd2(hH[n - 1]) : '-');
            this._set('customersDisplay', n ? this._fmtInt(cH[n - 1]) : '-');
            this._set('repDisplay', n ? this._fmtInt(rH[n - 1]) : '-');
            this._set('recordDisplay', n ? this._fmtInt(kH[n - 1]) : '-');
            this._set('hoursDisplay', n ? this._fmtDec(oH[n - 1]) : '-');
            this._set('taxDisplay', n ? this._fmtUsd(last.tax || 0) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state, period);
        }

        _fbKey(g, v) {
            var maps = {
                price1: { cheap: 'fb_pr_cheap', hourly: 'fb_pr_hourly', costed: 'fb_pr_costed', pro: 'fb_pr_pro' },
                gear1: { borrow: 'fb_ge_borrow', used: 'fb_ge_used', newkit: 'fb_ge_newkit', rent: 'fb_ge_rent' },
                mkt2: { word: 'fb_mk_word', hangers: 'fb_mk_hangers', ads: 'fb_mk_ads', mailbox: 'fb_mk_mailbox' },
                book2: { pocket: 'fb_bk_pocket', notebook: 'fb_bk_notebook', sheet: 'fb_bk_sheet', app: 'fb_bk_app' },
                cap3: { yesall: 'fb_cp_yesall', waitlist: 'fb_cp_waitlist', partner: 'fb_cp_partner', cut: 'fb_cp_cut' },
                add3: { none: 'fb_ad_none', hedges: 'fb_ad_hedges', pressure: 'fb_ad_pressure', weedfeed: 'fb_ad_weedfeed' },
                fall4: { keepall: 'fb_fa_keepall', weekend: 'fb_fa_weekend', stop: 'fb_fa_stop', sell: 'fb_fa_sell' },
                inc4: { own: 'fb_ic_own', deny: 'fb_ic_deny', herins: 'fb_ic_herins', half: 'fb_ic_half' }
            };
            return (maps[g] && maps[g][v]) ? maps[g][v] : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._summer(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

        getChartConfig() {
            return {
                profitChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Profit ($)', data: [], borderColor: '#2f6b3a', backgroundColor: 'rgba(47,107,58,0.12)', borderWidth: 2 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: false } } }
                },
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Round score', data: [], borderColor: '#2f6b3a', backgroundColor: 'rgba(47,107,58,0.35)', borderWidth: 1 },
                            { label: 'Reputation', data: [], borderColor: '#9a3412', backgroundColor: 'rgba(154,52,18,0.30)', borderWidth: 1 }
                        ]
                    },
                    options: { responsive: true, scales: { y: { beginAtZero: true, max: 100 } } }
                }
            };
        }

        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var profitHistory = ds.profitHistory || [];
            var repHistory = ds.repHistory || [];
            var scoreHistory = ds.scoreHistory || [];
            var self = this;
            var labels = profitHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); });
            return {
                profitChart: {
                    labels: labels,
                    datasets: [
                        { data: profitHistory.slice(), label: this._t('chart_profit') }
                    ]
                },
                scoreChart: {
                    labels: scoreHistory.map(function(x, i) { return self._t('round_label_short') + (i + 1); }),
                    datasets: [
                        { data: scoreHistory.slice(), label: this._t('chart_score') },
                        { data: repHistory.slice(), label: this._t('chart_rep') }
                    ]
                }
            };
        }

        getHistoryTableConfig() {
            var self = this;
            var usd = function(v) { return self._fmtUsd(v); };
            var usd2 = function(v) { return self._fmtUsd2(v); };
            var intf = function(v) { return self._fmtInt(v); };
            var decf = function(v) { return self._fmtDec(v); };
            return [
                { key: 'results.profit', label: 'Profit', i18nKey: 'col_profit', formatter: usd },
                { key: 'results.hourly', label: 'Profit per hour', i18nKey: 'col_hourly', formatter: usd2 },
                { key: 'results.customers', label: 'Weekly customers', i18nKey: 'col_customers', formatter: intf },
                { key: 'results.rep', label: 'Reputation', i18nKey: 'col_rep', formatter: intf },
                { key: 'results.record', label: 'Records and compliance', i18nKey: 'col_record', formatter: intf },
                { key: 'results.hours', label: 'Hours worked', i18nKey: 'col_hours', formatter: decf },
                { key: 'results.cum', label: 'Profit to date', i18nKey: 'col_cum', formatter: usd },
                { key: 'results.roundScore', label: 'Round score', i18nKey: 'col_score' }
            ];
        }

        getPerformanceSummary(history) {
            var state = window.mySimulation.state;
            var n = this._completed(state);
            var mm = Math.max(1, n);
            var m = this._summer(this._flat(state, mm), mm);
            var composite = this._composite(state);
            var insights = [];
            var self = this;
            var d = this._flat(state, mm);
            var shown = this.KEYS.filter(function(g) { return self.ROUND_OF[g] <= mm; });
            shown.forEach(function(g) { insights.push(self._t(self._fbKey(g, self._active(d, mm, g)))); });
            if (m.hard > 0) { insights.push(this._t('cm_cap')); }
            if (mm >= 4 && m.kept < 0.75 * m.served) {
                insights.push(this._t('cm_kept').replace('{served}', this._fmtInt(m.served))
                    .replace('{kept}', this._fmtInt(m.kept)).replace('{rep}', this._fmtInt(m.rep)));
            }
            insights.push(this._t('fb_next'));
            var turn = this._turningPoint(state, mm, composite);
            var vk = this._verdictKey(composite);
            var hrs = m.per.map(function(x) { return x.hours; });
            var totalHours = this._sum(hrs);
            return {
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: vk.replace('verdict_', ''),
                performanceLabel: this._t(vk),
                cum: Math.round(m.cum),
                hours: Math.round(totalHours * 10) / 10,
                avg: (totalHours > 0) ? Math.round(m.cum / totalHours * 100) / 100 : 0,
                customers: m.kept,
                rep: Math.round(m.rep),
                record: Math.round(m.rec),
                tax: Math.round(m.se),
                hard: m.hard,
                periods: (history || []).length,
                insights: insights,
                turningPoint: turn
            };
        }

        _turningPoint(state, mm, composite) {
            var d = (state && state.decisions) || {};
            var best = null, bestGain = 0, self = this;
            this.KEYS.forEach(function(g) {
                var r = self.ROUND_OF[g];
                if (r > mm) { return; }
                var rec = d['round' + r] || {};
                var chosen = (rec[g] === undefined || rec[g] === null) ? self.DEFAULTS[g] : rec[g];
                if (chosen === self.BEST[g]) { return; }
                var alt = {};
                Object.keys(d).forEach(function(k) {
                    var src = d[k] || {};
                    var cp = {};
                    Object.keys(src).forEach(function(x) { cp[x] = src[x]; });
                    alt[k] = cp;
                });
                alt['round' + r] = alt['round' + r] || {};
                alt['round' + r][g] = self.BEST[g];
                var sc = self._composite({ decisions: alt });
                if (sc - composite > bestGain) { bestGain = sc - composite; best = { key: g, round: r, score: sc }; }
            });
            if (!best) { return this._t('cm_turn_none'); }
            return this._t('cm_turn').replace('{label}', this._t('lbl_' + best.key)).replace('{round}', String(best.round))
                .replace('{score}', String(best.score)).replace('{yours}', String(composite));
        }

